INSERT IGNORE INTO LIVROS_NOMES (NOME, CATALOGO_ID, ESTADO, MOTIVO, CRIADO_EM) SELECT J.NOME, C.ID, 'OK', LEFT(J.MOTIVO, 300), DATE_FORMAT(NOW() - INTERVAL 3 HOUR, '%Y-%m-%dT%H:%i:%s') FROM VW_LOTE_NOMES J JOIN LIVROS_CATALOGO C ON C.TITULO = J.TITULO COLLATE utf8mb4_0900_ai_ci WHERE J.CHAVE = '{{chave}}' AND J.CONF = 'alta' AND J.NOME <> ''